<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="container page-head"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><p class="eyebrow">Mua sắm</p><h1>Thanh toán</h1></div><section class="container section form-layout"><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><form class="form-card" method="post" action="/checkout"><?= Csrf::field() ?><label for="name">Họ và tên</label><input id="name" name="shipping_name" type="text" required><label for="phone">Số điện thoại</label><input id="phone" name="shipping_phone" type="tel" required><label for="address">Địa chỉ nhận hàng</label><textarea id="address" name="shipping_address" rows="4" required></textarea><label for="voucher">Mã giảm giá (nếu có)</label><input id="voucher" name="voucher_code" type="text" maxlength="50" placeholder="Nhập mã voucher" value="<?= ViewHelper::escape((string)($voucherCode ?? '')) ?>"><fieldset class="payment-options"><legend>Phương thức thanh toán</legend><label><input type="radio" name="payment_method" value="cod" <?= ($paymentMethod ?? 'cod') === 'cod' ? 'checked' : '' ?>> Thanh toán khi nhận hàng (COD)</label><label><input type="radio" name="payment_method" value="payos" <?= ($paymentMethod ?? '') === 'payos' ? 'checked' : '' ?>> Chuyển khoản online qua PayOS (VietQR)</label></fieldset><button class="button button-primary" type="submit">Tiếp tục thanh toán</button></form></section>
